import xml.etree.ElementTree as ET

tree = ET.parse("robot.xml")
root = tree.getroot()

# ---- Resolve defaults ----
# class -> {joint: {axis, range}, position: {ctrlrange}}
defaults = {}

def parse_defaults(elem, inherited=None):
    cls = elem.get("class", "__root__")
    d = dict(inherited or {})
    for child in elem:
        tag = child.tag
        if tag == "default":
            parse_defaults(child, d)
            continue
        if tag not in d:
            d[tag] = {}
        d[tag].update({k: v for k, v in child.attrib.items()})
    defaults[cls] = d

default_root = root.find("default")
if default_root is not None:
    parse_defaults(default_root)

print("Default classes found:", list(defaults.keys()))
for cls, d in defaults.items():
    print(f"  [{cls}]")
    for tag, attrs in d.items():
        print(f"    {tag}: {attrs}")
