import xml.etree.ElementTree as ET, os

# Find robot.xml
robot_path = None
for root_dir, dirs, files in os.walk("/Users/wangyifan/Projects/auto_adapter2.0/AA1/assets/mjcf/capabilities/unitree_a1"):
    for f in files:
        if f == "robot.xml":
            robot_path = os.path.join(root_dir, f)
            break

print("robot.xml path:", robot_path)

tree = ET.parse(robot_path)
root = tree.getroot()

# ---- Collect joints ----
joints = []
for j in root.iter("joint"):
    if j.get("name"):  # skip freejoint (no name attr in <freejoint/>)
        joints.append({
            "name": j.get("name"),
            "type": j.get("type", "hinge"),
            "axis": j.get("axis"),
            "range": j.get("range"),
            "class": j.get("class"),
        })

print("\n=== JOINTS ===")
for j in joints:
    print(j)

# ---- Collect actuators ----
actuators = []
for act in root.iter("position"):
    actuators.append({
        "name": act.get("name"),
        "joint": act.get("joint"),
        "class": act.get("class"),
        "ctrlrange": act.get("ctrlrange"),
    })

print("\n=== ACTUATORS ===")
for a in actuators:
    print(a)

# ---- Collect sites ----
sites = []
for s in root.iter("site"):
    sites.append({"name": s.get("name"), "body": None})
print("\n=== SITES ===", sites)

# ---- Freejoint bodies ----
free_bodies = []
for b in root.iter("body"):
    for child in b:
        if child.tag == "freejoint":
            free_bodies.append(b.get("name"))
print("\n=== FREE JOINT BODIES ===", free_bodies)

# ---- Leaf bodies ----
def get_leaves(elem):
    children_bodies = [c for c in elem if c.tag == "body"]
    if not children_bodies:
        return [elem.get("name")]
    leaves = []
    for c in children_bodies:
        leaves.extend(get_leaves(c))
    return leaves

wb = root.find("worldbody")
leaves = []
for b in wb:
    if b.tag == "body":
        leaves.extend(get_leaves(b))
print("\n=== LEAF BODIES ===", leaves)
