# ---- Flatten defaults by class name ----
# Walk <default> tree; each <default class="X"> inherits from parent
class_defaults = {}

def walk_defaults(elem, parent_attrs=None):
    """elem is a <default> element."""
    cls = elem.get("class", "__root__")
    attrs = {}
    if parent_attrs:
        for tag, d in parent_attrs.items():
            attrs[tag] = dict(d)
    # merge this level's direct children (non-default tags)
    for child in elem:
        if child.tag == "default":
            walk_defaults(child, attrs)
        else:
            if child.tag not in attrs:
                attrs[child.tag] = {}
            attrs[child.tag].update(child.attrib)
    class_defaults[cls] = attrs

default_root = root.find("default")
if default_root is not None:
    # The outer <default> has no class; its child has class="a1"
    for child in default_root:
        if child.tag == "default":
            walk_defaults(child)

print("Classes:", list(class_defaults.keys()))
for cls, d in class_defaults.items():
    print(f"  [{cls}]")
    for tag, attrs in d.items():
        print(f"    {tag}: {attrs}")
